// Oeste GhostNumber — Mesa theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Mesa tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/mesa/src/index.js
// Docs: https://oeste.hiddeninwest.com/mesa/#/components/ghost-number

const SERIF = "font-['Merriweather',Georgia,'Times_New_Roman',serif]";

export function GhostNumber({ children }) {
  return (
    <span aria-hidden="true" className={`${SERIF} pointer-events-none absolute right-0 top-0 select-none text-[118px] font-black leading-none text-[#181b1f] opacity-[0.06] dark:text-[#ece3d0]`}>{children}</span>
  );
}
